(()=>{
  const root=document.querySelector('[data-v7-root]'); if(!root)return;
  const state=(()=>{try{return JSON.parse(document.getElementById('v7State')?.textContent||'{}')}catch{return {}}})();
  const $=(s,p=document)=>p.querySelector(s), $$=(s,p=document)=>[...p.querySelectorAll(s)];
  const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const lines=s=>esc(s).replace(/\n/g,'<br>');
  const send=async(url,method='GET',body)=>{const r=await fetch(url,{method,headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});const b=await r.json().catch(()=>({}));if(!r.ok)throw Error(b.detail||'Request failed');return b};
  const toast=(msg,bad=false)=>{const n=document.createElement('div');n.className=`v6-toast${bad?' bad':''}`;n.textContent=msg;document.body.appendChild(n);requestAnimationFrame(()=>n.classList.add('show'));setTimeout(()=>{n.classList.remove('show');setTimeout(()=>n.remove(),240)},2600)};
  const fmtBytes=n=>{n=Number(n||0);if(n<1024)return `${n} B`;if(n<1048576)return `${(n/1024).toFixed(1)} KB`;if(n<1073741824)return `${(n/1048576).toFixed(1)} MB`;return `${(n/1073741824).toFixed(2)} GB`};
  const statusClass=s=>String(s||'').replace(/[^a-z0-9_-]+/gi,'_').toLowerCase();
  const kindIcon=k=>({lore:'✦',character:'♟',monster:'♜',creature:'♜',npc:'♟',item:'◇',feat:'✦',faction:'⌘',place:'⌖',organization:'⌘',weapon:'⚔'}[String(k||'').toLowerCase()]||'◇');
  const entityById=id=>(state.entities||[]).find(e=>String(e.id)===String(id));
  const memberById=id=>(state.members||[]).find(e=>String(e.id)===String(id));
  const sessionId=()=>state.session?.id||null;

  // -----------------------------------------------------------------------
  // Workspace shell
  // -----------------------------------------------------------------------
  function switchTab(name){
    $$('[data-v7-tab]').forEach(b=>b.classList.toggle('active',b.dataset.v7Tab===name));
    $$('[data-v7-pane]').forEach(p=>p.classList.toggle('active',p.dataset.v7Pane===name));
    try{history.replaceState(null,'',`#${name}`)}catch{}
    if(name==='assets')loadAssets();
    if(name==='access')renderAccess();
  }
  $$('[data-v7-tab]').forEach(b=>b.addEventListener('click',()=>switchTab(b.dataset.v7Tab)));
  $$('[data-v7-jump]').forEach(b=>b.addEventListener('click',()=>switchTab(b.dataset.v7Jump)));
  const initialHash=location.hash.replace('#',''); if($(`[data-v7-tab="${CSS.escape(initialHash)}"]`))switchTab(initialHash);

  // -----------------------------------------------------------------------
  // Drawer
  // -----------------------------------------------------------------------
  const drawer=$('#v7Drawer'),drawerBody=$('#v7DrawerBody'),drawerTitle=$('#v7DrawerTitle'),drawerEyebrow=$('#v7DrawerEyebrow');
  function openDrawer(title,eyebrow,html,onOpen){drawerTitle.textContent=title;drawerEyebrow.textContent=eyebrow;drawerBody.innerHTML=html;drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';if(onOpen)onOpen(drawerBody)}
  function closeDrawer(){drawer.classList.remove('open');drawer.setAttribute('aria-hidden','true');document.body.style.overflow='';}
  $$('[data-v7-drawer-close]').forEach(b=>b.addEventListener('click',closeDrawer));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&drawer.classList.contains('open'))closeDrawer()});
  const formValue=(form,name)=>form.elements[name]?.value??'';
  const checked=(form,name)=>!!form.elements[name]?.checked;
  const field=(label,name,value='',opts={})=>`<label class="v7-field ${opts.wide?'wide':''}">${esc(label)}${opts.type==='textarea'?`<textarea name="${esc(name)}" placeholder="${esc(opts.placeholder||'')}">${esc(value||'')}</textarea>`:opts.options?`<select name="${esc(name)}">${opts.options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select>`:`<input name="${esc(name)}" type="${esc(opts.type||'text')}" value="${esc(value??'')}" placeholder="${esc(opts.placeholder||'')}">`}</label>`;

  async function refreshState(){
    try{const fresh=await send('/api/v7/workspace');Object.assign(state,fresh);renderAll();}catch(err){toast(err.message,true)}
  }

  // -----------------------------------------------------------------------
  // Table cockpit
  // -----------------------------------------------------------------------
  function renderScenes(){
    const host=$('#v7SceneRail'); if(!host)return;const scenes=state.scenes||[];
    if(!scenes.length){host.innerHTML='<div class="v7-empty"><span>✎</span><h3>No scene cards yet.</h3><p>Open Session Prep to sketch the runbook, or use the classic console.</p></div>';return}
    host.innerHTML=scenes.map((s,i)=>`<article class="v7-scene-card ${s.status==='active'?'current':''} ${s.status==='done'?'done':''}"><span>SCENE ${String(i+1).padStart(2,'0')} · ${esc(s.status||'ready')}</span><h3>${esc(s.title||'Untitled scene')}</h3><p>${esc(s.purpose||s.complication||'No purpose noted.')}</p><footer><button class="v7-button ghost small" data-scene-state="active" data-scene-id="${s.id}">Now</button><button class="v7-button ghost small" data-scene-state="done" data-scene-id="${s.id}">Done</button></footer></article>`).join('');
    $$('[data-scene-state]',host).forEach(btn=>btn.addEventListener('click',async()=>{
      const row=scenes.find(x=>String(x.id)===btn.dataset.sceneId);if(!row||!state.session)return;
      row.status=btn.dataset.sceneState;
      if(row.status==='active')scenes.forEach(x=>{if(x!==row&&x.status==='active')x.status='ready'});
      try{await send(`/api/v51/gm/scenes/${state.session.id}`,'PUT',{scenes});toast('Scene state updated.');renderScenes()}catch(err){toast(err.message,true)}
    }));
  }
  function renderWarnings(){
    const rows=state.warnings||state.dashboard?.warnings||[];$('#v7WarningCount').textContent=String(rows.length);
    const html=rows.length?rows.slice(0,8).map(w=>`<article class="v7-stack-item ${esc(w.severity||'warning')}"><strong>${esc(w.entity?.name||'World-state check')}</strong><small>${esc(w.message||'Potential contradiction')}</small></article>`).join(''):'<article class="v7-stack-item ok"><strong>No active contradictions</strong><small>Upcoming prep agrees with the world state Seeker can verify.</small></article>';
    $('#v7Warnings').innerHTML=html;$('#v7LogicWarnings').innerHTML=html;
  }
  function renderChanges(){
    const rows=state.changes||[];const peek=$('#v7ChangePeek');peek.innerHTML=rows.length?rows.slice(-6).reverse().map(c=>`<article class="v7-stack-item"><strong>${esc(c.summary)}</strong><small>${esc(c.status)} · ${esc(c.kind)}</small></article>`).join(''):'<article class="v7-stack-item"><strong>No changes recorded yet</strong><small>Use “Record change” during play so the closeout has a reliable memory.</small></article>';
  }
  function renderFronts(){const host=$('#v7FrontPeek');const rows=state.fronts||[];host.innerHTML=rows.length?rows.slice(0,5).map(f=>`<article class="v7-stack-item"><strong>${esc(f.title)}</strong><small>${esc(f.goal||f.next_move||'No next move recorded.')} · ${Number(f.current_value||0)}/${Number(f.max_value||6)}</small></article>`).join(''):'<p class="v7-muted">No active fronts.</p>'}
  function renderSyncSummary(){const counts=state.dashboard?.sync_counts||{};$('#v7SyncPeek').innerHTML=[['synced','Synced'],['seeker_changed','Seeker changed'],['foundry_changed','Foundry changed'],['conflict','Conflict']].map(([k,l])=>`<div><strong>${Number(counts[k]||0)}</strong><small>${l}</small></div>`).join('')}

  $('[data-v7-quick-change]')?.addEventListener('click',()=>openQuickChange());$('[data-v7-review]')?.addEventListener('click',()=>openSessionReview());
  function openQuickChange(){
    if(!state.session)return toast('Create or select a session first.',true);
    const entityOptions=(state.entities||[]).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('');
    openDrawer('Record campaign change','SESSION MEMORY',`<form id="v7QuickChangeForm"><div class="v7-editor-section"><h3>What changed?</h3>${field('Summary','summary','',{wide:true,placeholder:'Captain Rell died defending the west gate.'})}<div class="v7-form-grid">${field('Change type','kind','event',{options:[['event','Event / note'],['entity_status','Entity status'],['relationship','Relationship'],['knowledge','Knowledge'],['front','Front progress']]})}<label class="v7-field">Related entity<select name="entity_id"><option value="">None</option>${entityOptions}</select></label></div>${field('New status (if relevant)','status','',{placeholder:'dead, hostile, missing…'})}<label class="v7-field wide"><span>Visible to players</span><input name="visible" type="checkbox" style="width:auto"></label></div><div class="v7-form-actions"><button type="button" class="v7-button ghost" data-v7-cancel>Cancel</button><button class="v7-button">Add to review</button></div></form>`,body=>{
      $('[data-v7-cancel]',body).onclick=closeDrawer;$('#v7QuickChangeForm',body).onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;const kind=formValue(f,'kind'),entity=formValue(f,'entity_id');const payload={kind,entity_id:entity?Number(entity):null,summary:formValue(f,'summary'),visible_to_players:checked(f,'visible'),payload:{status:formValue(f,'status')}};try{const row=await send(`/api/v7/session/${state.session.id}/changes`,'POST',payload);state.changes.push(row);renderChanges();toast('Change added to session review.');closeDrawer()}catch(err){toast(err.message,true)}};
    });
  }
  function openSessionReview(){
    if(!state.session)return toast('No current session.',true);
    const html=`<section class="v7-editor-section"><h3>${esc(state.session.title)}</h3><p class="v7-muted">Approve what should become campaign state. Reject false starts. Nothing writes itself into LaTeX canon.</p><div id="v7ReviewRows" class="v7-stack"></div></section><form id="v7FinishForm"><section class="v7-editor-section"><h3>Closeout</h3>${field('Session summary','summary',state.session.summary||'',{type:'textarea',wide:true,placeholder:'What happened, in a paragraph future-you will understand.'})}${field('Unresolved / carry forward','unresolved','',{type:'textarea',wide:true,placeholder:'Loose threads, delayed consequences, unfinished scenes…'})}</section><div class="v7-form-actions"><button class="v7-button ghost" type="button" data-v7-cancel>Keep session open</button><button class="v7-button" type="submit">Finish session</button></div></form>`;
    openDrawer('Resolve this session','RESOLVE → REMEMBER',html,body=>{
      const renderRows=()=>{$('#v7ReviewRows',body).innerHTML=(state.changes||[]).length?(state.changes||[]).map(c=>`<article class="v7-stack-item"><strong>${esc(c.summary)}</strong><small>${esc(c.kind)} · ${esc(c.status)}</small><div class="v7-card-actions">${c.status==='proposed'?`<button class="v7-button ghost small" data-review-status="approved" data-change-id="${c.id}">Approve</button><button class="v7-button ghost small" data-review-status="rejected" data-change-id="${c.id}">Reject</button>`:''}${c.status==='approved'?`<button class="v7-button small" data-review-status="applied" data-change-id="${c.id}">Apply now</button>`:''}</div></article>`).join(''):'<div class="v7-empty"><p>No changes were recorded.</p></div>';$$('[data-review-status]',body).forEach(b=>b.onclick=async()=>{try{const row=await send(`/api/v7/session-changes/${b.dataset.changeId}/review`,'POST',{status:b.dataset.reviewStatus,session_id:state.session.id});const i=state.changes.findIndex(x=>String(x.id)===String(row.id));if(i>=0)state.changes[i]={...state.changes[i],...row};renderRows();renderChanges();toast(`Change ${b.dataset.reviewStatus}.`)}catch(err){toast(err.message,true)}})};renderRows();
      $('[data-v7-cancel]',body).onclick=closeDrawer;$('#v7FinishForm',body).onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;if((state.changes||[]).some(c=>c.status==='proposed')&&!confirm('Some changes are still unreviewed. Finish the session anyway?'))return;try{await send(`/api/v7/session/${state.session.id}/finish`,'POST',{summary:formValue(f,'summary'),unresolved:formValue(f,'unresolved')});toast('Session closed and approved state applied.');closeDrawer();await refreshState()}catch(err){toast(err.message,true)}};
    });
  }

  // -----------------------------------------------------------------------
  // Entities
  // -----------------------------------------------------------------------
  let entityFilter='all',entityQuery='';
  function renderEntityKinds(){const kinds={all:(state.entities||[]).length};for(const e of state.entities||[])kinds[e.kind]=(kinds[e.kind]||0)+1;$('#v7EntityKinds').innerHTML=Object.entries(kinds).map(([k,n])=>`<button class="${entityFilter===k?'active':''}" data-entity-kind="${esc(k)}">${esc(k==='all'?'All':k)} · ${n}</button>`).join('');$$('[data-entity-kind]').forEach(b=>b.onclick=()=>{entityFilter=b.dataset.entityKind;renderEntities();renderEntityKinds()})}
  function renderEntities(){
    let rows=state.entities||[];if(entityFilter!=='all')rows=rows.filter(e=>e.kind===entityFilter);if(entityQuery)rows=rows.filter(e=>`${e.name} ${e.summary} ${(e.tags||[]).join(' ')}`.toLowerCase().includes(entityQuery));
    $('#v7EntityGrid').innerHTML=rows.length?rows.map(e=>`<article class="v7-entity-card" data-entity-card="${e.id}"><div class="v7-entity-art" ${e.image_ref?`style="background-image:url('${esc(e.image_ref)}')"`:''}><span>${kindIcon(e.kind)} ${esc(e.kind)}</span></div><div class="v7-entity-body"><h3>${esc(e.name)}</h3><p>${esc(e.summary||e.subtitle||'No summary yet.')}</p><div class="v7-tagrow"><span><i class="v7-sync-dot ${statusClass(e.sync?.status)}"></i> ${esc(e.sync?.status||'not linked')}</span>${(e.tags||[]).slice(0,2).map(t=>`<span>${esc(t)}</span>`).join('')}</div></div></article>`).join(''):'<div class="v7-empty"><h3>No matching entities.</h3></div>';
    $$('[data-entity-card]').forEach(c=>c.onclick=()=>openEntityEditor(Number(c.dataset.entityCard)));
    const relationCount=(state.entities||[]).reduce((n,e)=>n+Number(e.relations?.length||0),0);$('#v7RelationCount').textContent=relationCount||'—';
  }
  $('[data-v7-entity-search]')?.addEventListener('input',e=>{entityQuery=e.currentTarget.value.trim().toLowerCase();renderEntities()});$('[data-v7-new-entity]')?.addEventListener('click',()=>openEntityEditor(null));
  async function openEntityEditor(id){
    let entity=id?entityById(id):null,versions=[];if(id){try{[entity,versions]=await Promise.all([send(`/api/v7/entities/${id}`),send(`/api/v7/entities/${id}/versions`)])}catch(err){return toast(err.message,true)}}
    const e=entity||{kind:'npc',name:'',subtitle:'',summary:'',body:'',status:'active',visibility:'gm',tags:[],data:{},relations:[],facts:[]};
    const entityOptions=(state.entities||[]).filter(x=>!id||x.id!==id).map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(x.kind)}</option>`).join('');
    const memberOptions=(state.members||[]).map(m=>`<option value="${m.id}">${esc(m.label)}</option>`).join('');
    const body=`<div class="v7-editor-tabs"><button class="active" data-editor-tab="identity">Identity</button><button data-editor-tab="relationships">Relationships</button><button data-editor-tab="knowledge">Knowledge</button><button data-editor-tab="foundry">Foundry</button><button data-editor-tab="history">History</button></div>
    <section data-editor-pane="identity"><form id="v7EntityForm"><div class="v7-editor-section"><h3>Identity</h3><div class="v7-form-grid">${field('Name','name',e.name)}${field('Kind','kind',e.kind,{options:[['lore','Lore'],['npc','NPC'],['monster','Monster'],['character','Character'],['item','Item'],['feat','Feat'],['faction','Faction'],['place','Place'],['organization','Organization'],['other','Other']]})}${field('Subtitle','subtitle',e.subtitle,{wide:true})}${field('Status','status',e.status,{placeholder:'active, dead, missing…'})}${field('Visibility','visibility',e.visibility,{options:[['players','Players'],['gm','GM only']]})}${field('Tags','tags',(e.tags||[]).join(', '),{wide:true,placeholder:'faction, city, undead'})}${field('Summary','summary',e.summary,{type:'textarea',wide:true})}${field('Body / working notes','body',e.body,{type:'textarea',wide:true})}${field('Portrait / art','image_ref',e.image_ref,{wide:true})}${field('Token','token_ref',e.token_ref,{wide:true})}</div></div><div class="v7-form-actions"><button class="v7-button ghost" type="button" data-v7-cancel>Cancel</button>${id?'<button class="v7-button danger" type="button" data-v7-delete-entity>Delete</button>':''}<button class="v7-button">Save entity</button></div></form></section>
    <section class="hidden" data-editor-pane="relationships"><div class="v7-editor-section"><h3>Connections</h3><div id="v7EntityRelations" class="v7-stack">${(e.relations||[]).map(r=>`<article class="v7-stack-item"><strong>${esc(r.source_entity_id===id?r.target_name:r.source_name)}</strong><small>${esc(r.relation)} ${r.label?`· ${esc(r.label)}`:''}</small></article>`).join('')||'<p class="v7-muted">No relationships yet.</p>'}</div>${id?`<form id="v7RelationForm"><div class="v7-form-grid"><label class="v7-field">Connect to<select name="target_entity_id"><option value="">Choose…</option>${entityOptions}</select></label>${field('Relationship','relation','related to',{placeholder:'ally of, parent of, controls…'})}${field('Label / context','label','',{wide:true})}</div><button class="v7-button ghost" type="submit">＋ Add relationship</button></form>`:''}</div>${id?`<div class="v7-editor-section"><h3>Relationship state over time</h3><form id="v7RelationshipStateForm"><div class="v7-form-grid"><label class="v7-field">With<select name="target_entity_id"><option value="">Choose…</option>${entityOptions}</select></label>${field('State','state','friendly',{placeholder:'friendly, suspicious, betrayed…'})}${field('Moment / label','label','',{wide:true,placeholder:'After the Chapel confrontation'})}${field('Note','note','',{type:'textarea',wide:true})}</div><button class="v7-button ghost">Record state</button></form></div>`:''}</section>
    <section class="hidden" data-editor-pane="knowledge"><div class="v7-editor-section"><h3>Knowledge facts</h3><div id="v7Facts" class="v7-fact-grid">${(e.facts||[]).map(f=>`<article class="v7-fact-card"><header><h4>${esc(f.title)}</h4><span class="v7-tier">${esc(f.tier)}</span></header><p>${esc(f.body)}</p><div class="v7-card-actions"><button class="v7-button ghost small" type="button" data-edit-fact="${f.id}">Edit clue</button>${state.members?.length?`<select data-fact-player="${f.id}"><option value="">Reveal to…</option>${memberOptions}</select><button class="v7-button ghost small" data-reveal-fact="${f.id}">Reveal exact</button>`:''}</div></article>`).join('')||'<p class="v7-muted">No facts yet.</p>'}</div>${id?`<form id="v7FactForm"><input type="hidden" name="id" value=""><div class="v7-form-grid">${field('Fact title','title','')}${field('Tier','tier','known',{options:[['rumored','Rumored / public'],['known','Known'],['full','Full / mechanical']]})}${field('Exact reveal','body','',{type:'textarea',wide:true,placeholder:'Resistance 10 fire.'})}${field('Vague reveal','vague_body','',{type:'textarea',wide:true,placeholder:'It has a massive weakness to fire, but you cannot judge the exact severity.'})}${field('Comparative reveal','comparative_body','',{type:'textarea',wide:true,placeholder:'Fortitude is its strongest save.'})}</div><p class="v7-form-hint">Exact is the full mechanic. Vague hides numbers. Comparative reveals ranking or relative strength without a value.</p><button class="v7-button ghost">＋ Add fact</button></form>`:''}</div></section>
    <section class="hidden" data-editor-pane="foundry"><div class="v7-editor-section"><h3>Managed Foundry document</h3>${e.sync?`<div class="v7-diff-columns"><div><small>SEEKER</small><strong>${esc(e.name)}</strong></div><div><small>FOUNDRY</small><strong>${esc(e.sync.foundry_snapshot?.name||e.sync.foundry_uuid)}</strong></div></div><p class="v7-sync-state ${statusClass(e.sync.status)}">${esc(e.sync.status)}</p>${(e.sync.diffs||[]).length?`<div class="v7-diff-list">${e.sync.diffs.slice(0,12).map(d=>`<div><strong>${esc(d.field)}</strong><span>${esc(JSON.stringify(d.seeker))}</span><i>→</i><span>${esc(JSON.stringify(d.foundry))}</span></div>`).join('')}</div>`:'<p class="v7-muted">No comparable PF2e fields differ.</p>'}<div class="v7-card-actions"><button class="v7-button" data-entity-sync="push">Push Seeker → Foundry</button>${e.sync.status==='foundry_changed'||e.sync.status==='conflict'?'<button class="v7-button ghost" data-entity-sync="accept_foundry">Accept Foundry snapshot</button>':''}</div>`:`<p class="v7-muted">This entity is not linked yet. Seeker will remember the Foundry UUID after the first successful push.</p><button class="v7-button" data-entity-sync="push">Create in Foundry</button>`}</div><div class="v7-danger-note">Only Foundry documents carrying this entity's Seeker management flag are eligible for updates. Changing an item's Foundry document type is intentionally blocked.</div></section>
    <section class="hidden" data-editor-pane="history"><div class="v7-editor-section"><h3>Version history</h3>${versions.map(v=>`<article class="v7-version-row"><div><strong>Version ${v.version_no}</strong><small>${v.created_by?`${esc(v.created_by)} · `:''}${new Date(Number(v.created_at||0)*1000).toLocaleString()}</small></div><button class="v7-button ghost small" data-restore-version="${v.id}" ${v.version_no===versions[0]?.version_no?'disabled':''}>Restore</button></article>`).join('')||'<p class="v7-muted">No saved versions yet.</p>'}</div><div class="v7-editor-section"><h3>Appearances</h3>${(e.sessions||[]).map(s=>`<article class="v7-stack-item"><strong>${esc(s.session_title||'Session')}</strong><small>${esc(s.role)} ${s.note?`· ${esc(s.note)}`:''}</small></article>`).join('')||'<p class="v7-muted">No session appearances recorded through the Living Table yet.</p>'}</div></section>`;
    openDrawer(id?e.name:'New entity','ENTITY',body,bodyEl=>{
      $$('[data-editor-tab]',bodyEl).forEach(b=>b.onclick=()=>{$$('[data-editor-tab]',bodyEl).forEach(x=>x.classList.toggle('active',x===b));$$('[data-editor-pane]',bodyEl).forEach(p=>p.classList.toggle('hidden',p.dataset.editorPane!==b.dataset.editorTab))});
      $('[data-v7-cancel]',bodyEl)?.addEventListener('click',closeDrawer);
      $('#v7EntityForm',bodyEl).onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget;const payload={id:id||undefined,name:formValue(f,'name'),kind:formValue(f,'kind'),subtitle:formValue(f,'subtitle'),status:formValue(f,'status'),visibility:formValue(f,'visibility'),tags:formValue(f,'tags').split(',').map(x=>x.trim()).filter(Boolean),summary:formValue(f,'summary'),body:formValue(f,'body'),image_ref:formValue(f,'image_ref'),token_ref:formValue(f,'token_ref'),data:e.data||{}};try{await send('/api/v7/entities','POST',payload);toast('Entity saved.');closeDrawer();await refreshState()}catch(err){toast(err.message,true)}};
      $('[data-v7-delete-entity]',bodyEl)?.addEventListener('click',async()=>{if(!confirm(`Delete ${e.name} from the Living Table registry? Its legacy source is not deleted.`))return;try{await send(`/api/v7/entities/${id}`,'DELETE');toast('Entity registry entry deleted.');closeDrawer();await refreshState()}catch(err){toast(err.message,true)}});
      $('#v7RelationForm',bodyEl)?.addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.currentTarget;if(!formValue(f,'target_entity_id'))return toast('Choose another entity.',true);try{await send(`/api/v7/entities/${id}/relations`,'POST',{target_entity_id:Number(formValue(f,'target_entity_id')),relation:formValue(f,'relation'),label:formValue(f,'label'),visibility:'players'});toast('Relationship added.');closeDrawer();await refreshState();openEntityEditor(id)}catch(err){toast(err.message,true)}});
      $('#v7RelationshipStateForm',bodyEl)?.addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.currentTarget;if(!formValue(f,'target_entity_id'))return toast('Choose another entity.',true);try{await send(`/api/v7/entities/${id}/relationship-state`,'POST',{target_entity_id:Number(formValue(f,'target_entity_id')),state:formValue(f,'state'),label:formValue(f,'label'),note:formValue(f,'note'),session_id:sessionId()});toast('Relationship state recorded.')}catch(err){toast(err.message,true)}});
      $('#v7FactForm',bodyEl)?.addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.currentTarget;try{await send(`/api/v7/entities/${id}/facts`,'POST',{id:formValue(f,'id')?Number(formValue(f,'id')):undefined,title:formValue(f,'title'),tier:formValue(f,'tier'),body:formValue(f,'body'),vague_body:formValue(f,'vague_body'),comparative_body:formValue(f,'comparative_body')});toast(formValue(f,'id')?'Knowledge clue updated.':'Knowledge fact added.');closeDrawer();await refreshState();openEntityEditor(id)}catch(err){toast(err.message,true)}});
      $$('[data-edit-fact]',bodyEl).forEach(b=>b.onclick=()=>{const fact=(e.facts||[]).find(x=>String(x.id)===String(b.dataset.editFact)),f=$('#v7FactForm',bodyEl);if(!fact||!f)return;const d=fact.mechanics?.disclosures||{};f.elements.id.value=fact.id;f.elements.title.value=fact.title||'';f.elements.tier.value=fact.tier||'known';f.elements.body.value=fact.body||'';f.elements.vague_body.value=d.vague?.body||'';f.elements.comparative_body.value=d.comparative?.body||'';const submit=f.querySelector('button[type=submit],button:not([type])');if(submit)submit.textContent='Save clue changes';f.scrollIntoView({behavior:'smooth',block:'center'})});
      $$('[data-reveal-fact]',bodyEl).forEach(b=>b.onclick=async()=>{const select=$(`[data-fact-player="${b.dataset.revealFact}"]`,bodyEl);if(!select?.value)return toast('Choose a player.',true);try{await send(`/api/v7/facts/${b.dataset.revealFact}/reveal`,'POST',{invite_id:Number(select.value),session_id:sessionId()});toast('Fact revealed.')}catch(err){toast(err.message,true)}});
      $$('[data-entity-sync]',bodyEl).forEach(b=>b.onclick=async()=>{if(!id)return toast('Save the entity first.',true);try{const out=await send(`/api/v7/entities/${id}/foundry`,'POST',{mode:b.dataset.entitySync});toast(out.command?'Foundry action queued.':'Sync state updated.');closeDrawer();setTimeout(refreshState,900)}catch(err){toast(err.message,true)}});
      $$('[data-restore-version]',bodyEl).forEach(b=>b.onclick=async()=>{if(!id||b.disabled)return;if(!confirm('Restore this entity version? Seeker will keep the current version in history so the restore can be undone.'))return;try{await send(`/api/v7/entities/${id}/versions/${b.dataset.restoreVersion}/restore`,'POST');toast('Entity version restored.');closeDrawer();await refreshState();openEntityEditor(id)}catch(err){toast(err.message,true)}});
    });
  }

  // -----------------------------------------------------------------------
  // Creature Vault / Archives of Nethys
  // -----------------------------------------------------------------------
  const aonEntities=()=> (state.entities||[]).filter(e=>['monster','creature','npc'].includes(String(e.kind||'').toLowerCase()) && e.data?.aon_url);
  function renderCreatureVault(){
    const folders=state.creature_folders||[],folderHost=$('#v7CreatureFolders');
    if(folderHost)folderHost.innerHTML=folders.length?folders.map(f=>`<article class="v7-folder-card"><header><div><span>COLLECTION</span><h3>${esc(f.name)}</h3><small>${(f.members||[]).length} creature${(f.members||[]).length===1?'':'s'}${f.source==='aon'?' · AoN':''}</small></div><button class="v7-inline-icon" data-edit-creature-folder="${f.id}" title="Edit collection">•••</button></header><p>${esc(f.note||'A reusable creature collection. Bulk push creates a matching Foundry Actor folder.')}</p><div class="v7-folder-members">${(f.members||[]).slice(0,8).map(e=>`<span>${esc(e.name)}</span>`).join('')}${(f.members||[]).length>8?`<span>+${(f.members||[]).length-8}</span>`:''}</div><footer><button class="v7-button ghost small" data-push-creature-folder="${f.id}">⬡ Push folder</button><button class="v7-button ghost small" data-import-folder="${f.id}">⇣ Import links</button></footer></article>`).join(''):'<div class="v7-empty compact"><span>◇</span><h3>No collections yet.</h3><p>Create one for an adventure, region, faction, or bestiary set.</p></div>';
    const q=String($('#v7CreatureSearch')?.value||'').trim().toLowerCase();
    const rows=aonEntities().filter(e=>!q||`${e.name} ${(e.tags||[]).join(' ')} ${e.data?.aon_source||''}`.toLowerCase().includes(q));
    const host=$('#v7AonCreatures');if(host)host.innerHTML=rows.length?rows.map(e=>`<article class="v7-aon-card"><div class="v7-aon-art" ${e.image_ref?`style="background-image:url('${esc(e.image_ref)}')"`:''}><span>${e.image_ref?'':'♜'}</span></div><div class="v7-aon-copy"><div class="v7-card-meta"><span>Level ${esc(e.data?.level??'?')}</span><span>${esc(e.data?.rarity||'common')}</span><span>AoN</span></div><h3>${esc(e.name)}</h3><p>${esc(e.summary||e.data?.aon_source||'Imported Archives of Nethys creature.')}</p><div class="v7-trait-row">${(e.tags||[]).slice(0,7).map(t=>`<span>${esc(t)}</span>`).join('')}</div><footer><button class="v7-button ghost small" data-aon-entity="${e.id}">Open dossier</button><button class="v7-button small" data-aon-push="${e.id}">⬡ Foundry</button><a class="v7-button ghost small" href="${esc(e.data?.aon_url||'#')}" target="_blank" rel="noopener">Source ↗</a></footer></div></article>`).join(''):'<div class="v7-empty"><span>♜</span><h3>No AoN creatures imported.</h3><p>Paste one or many creature links. Seeker stores the parsed monster, not a copy of the webpage.</p><button class="v7-button" data-empty-import-aon>⇣ Import from Archives of Nethys</button></div>';
    $$('[data-edit-creature-folder]').forEach(b=>b.onclick=()=>openCreatureFolderEditor(Number(b.dataset.editCreatureFolder)));
    $$('[data-push-creature-folder]').forEach(b=>b.onclick=async()=>{try{const out=await send(`/api/v7/creature-folders/${b.dataset.pushCreatureFolder}/push-foundry`,'POST');toast(`${out.count} creature${out.count===1?'':'s'} queued for “${out.folder_name}”.`);setTimeout(refreshState,800)}catch(err){toast(err.message,true)}});
    $$('[data-import-folder]').forEach(b=>b.onclick=()=>openAonImporter(null,Number(b.dataset.importFolder)));
    $$('[data-aon-entity]').forEach(b=>b.onclick=()=>openEntityEditor(Number(b.dataset.aonEntity)));
    $$('[data-aon-push]').forEach(b=>b.onclick=()=>syncEntity(b.dataset.aonPush,'push'));
    $('[data-empty-import-aon]')?.addEventListener('click',()=>openAonImporter());
  }
  $('#v7CreatureSearch')?.addEventListener('input',renderCreatureVault);
  $('[data-v7-import-aon]')?.addEventListener('click',()=>openAonImporter());
  $('[data-v7-import-aon-encounter]')?.addEventListener('click',()=>openAonImporter((state.encounters||[])[0]?.id||null));
  $('[data-v7-new-creature-folder]')?.addEventListener('click',()=>openCreatureFolderEditor(null));

  function openCreatureFolderEditor(id){
    const folder=id?(state.creature_folders||[]).find(x=>Number(x.id)===Number(id)):null;
    const members=folder?.members||[];
    const available=(state.entities||[]).filter(e=>['monster','creature','npc'].includes(e.kind)&&!members.some(m=>Number(m.id)===Number(e.id)));
    const html=`<form id="v7CreatureFolderForm"><div class="v7-editor-section"><h3>${id?'Collection details':'New creature collection'}</h3><div class="v7-form-grid">${field('Name','name',folder?.name||'',{placeholder:'Abomination Vaults · Floor 3'})}${field('Notes','note',folder?.note||'',{type:'textarea',wide:true,placeholder:'What this collection is for…'})}</div></div><div class="v7-form-actions"><button type="button" class="v7-button ghost" data-v7-cancel>Cancel</button>${id?'<button type="button" class="v7-button danger ghost" data-delete-creature-folder>Delete collection</button>':''}<button class="v7-button">Save collection</button></div></form>${id?`<div class="v7-editor-section"><div class="v7-inline-head"><h3>Creatures</h3><button class="v7-button ghost small" type="button" data-folder-import-aon>⇣ Import AoN</button></div><div class="v7-folder-editor-members">${members.map(e=>`<article><div><strong>${esc(e.name)}</strong><small>${e.data?.aon_url?'Archives of Nethys':'Seeker'} · Level ${esc(e.data?.level??'?')}</small></div><button class="v7-inline-icon" data-folder-remove="${e.id}" type="button">×</button></article>`).join('')||'<p class="v7-muted">This collection is empty.</p>'}</div>${available.length?`<div class="v7-add-existing"><select id="v7FolderExisting"><option value="">Add an existing creature…</option>${available.map(e=>`<option value="${e.id}">${esc(e.name)} · L${esc(e.data?.level??'?')}</option>`).join('')}</select><button class="v7-button ghost small" type="button" data-folder-add-existing>Add</button></div>`:''}<button class="v7-button full" type="button" data-folder-push>⬡ Push entire collection to Foundry</button></div>`:''}`;
    openDrawer(folder?.name||'New collection','CREATURE VAULT',html,body=>{
      $('[data-v7-cancel]',body).onclick=closeDrawer;
      $('#v7CreatureFolderForm',body).onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget;try{await send('/api/v7/creature-folders','POST',{id:id||undefined,name:formValue(f,'name'),note:formValue(f,'note'),source:folder?.source||'manual'});toast('Creature collection saved.');closeDrawer();await refreshState()}catch(err){toast(err.message,true)}};
      $('[data-folder-import-aon]',body)?.addEventListener('click',()=>{closeDrawer();openAonImporter(null,id)});
      $('[data-folder-add-existing]',body)?.addEventListener('click',async()=>{const eid=Number($('#v7FolderExisting',body)?.value||0);if(!eid)return;try{await send(`/api/v7/creature-folders/${id}/members`,'POST',{entity_id:eid});toast('Creature added to collection.');closeDrawer();await refreshState();openCreatureFolderEditor(id)}catch(err){toast(err.message,true)}});
      $$('[data-folder-remove]',body).forEach(b=>b.onclick=async()=>{try{await send(`/api/v7/creature-folders/${id}/members/${b.dataset.folderRemove}`,'DELETE');closeDrawer();await refreshState();openCreatureFolderEditor(id)}catch(err){toast(err.message,true)}});
      $('[data-folder-push]',body)?.addEventListener('click',async()=>{try{const out=await send(`/api/v7/creature-folders/${id}/push-foundry`,'POST');toast(`${out.count} creature${out.count===1?'':'s'} queued in one Foundry folder.`);closeDrawer();setTimeout(refreshState,700)}catch(err){toast(err.message,true)}});
      $('[data-delete-creature-folder]',body)?.addEventListener('click',async()=>{if(!confirm('Delete this Seeker collection? The creatures themselves and Foundry actors are not deleted.'))return;try{await send(`/api/v7/creature-folders/${id}`,'DELETE');toast('Collection deleted.');closeDrawer();await refreshState()}catch(err){toast(err.message,true)}});
    });
  }

  function openAonImporter(encounterId=null,folderId=null){
    const folders=state.creature_folders||[],encounters=state.encounters||[];
    const html=`<form id="v7AonImportForm"><div class="v7-editor-section aon-import-hero"><span class="v7-big-glyph">⇣</span><div><span class="eyebrow">ARCHIVES OF NETHYS</span><h3>Import complete PF2e creatures</h3><p>Paste up to 25 Monsters.aspx or NPCs.aspx links, one per line. Seeker reads the stat block into a normal editable monster. It keeps the source URL, but does not archive the webpage HTML.</p></div></div><div class="v7-editor-section">${field('Creature links','urls','',{type:'textarea',wide:true,placeholder:'https://2e.aonprd.com/Monsters.aspx?ID=…\nhttps://2e.aonprd.com/Monsters.aspx?ID=…'})}<div class="v7-form-grid"><label class="v7-field">Collection<select name="folder_id"><option value="">No collection</option>${folders.map(f=>`<option value="${f.id}" ${Number(f.id)===Number(folderId)?'selected':''}>${esc(f.name)}</option>`).join('')}</select></label>${field('Or create collection','folder_name','',{placeholder:'Optional new collection'})}<label class="v7-field">Add directly to encounter<select name="encounter_id"><option value="">No encounter</option>${encounters.map(e=>`<option value="${e.id}" ${Number(e.id)===Number(encounterId)?'selected':''}>${esc(e.title)}</option>`).join('')}</select></label>${field('Codex visibility','codex_visibility','field_notes',{options:[['field_notes','Field notes — hide mechanics'],['full','Full statblock']]})}</div><div class="v7-option-grid"><label class="v7-check-card"><input type="checkbox" name="publish_codex"><span><strong>Add to Monster Codex</strong><small>Players see only the visibility level selected above.</small></span></label><label class="v7-check-card"><input type="checkbox" name="refresh_existing"><span><strong>Refresh existing AoN entries</strong><small>Re-read mechanics while preserving Seeker artwork, token, GM notes and Codex settings.</small></span></label></div></div><div id="v7AonProgress" class="v7-import-progress hidden"><i></i><div><strong>Reading Archives of Nethys…</strong><small>Parsing creature statistics, attacks, actions and spellcasting.</small></div></div><div class="v7-form-actions"><button type="button" class="v7-button ghost" data-v7-cancel>Cancel</button><button class="v7-button" data-aon-submit>⇣ Import creatures</button></div></form>`;
    openDrawer('Archives of Nethys import','CREATURE VAULT',html,body=>{
      $('[data-v7-cancel]',body).onclick=closeDrawer;
      $('#v7AonImportForm',body).onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget,btn=$('[data-aon-submit]',body),progress=$('#v7AonProgress',body);btn.disabled=true;progress.classList.remove('hidden');try{const out=await send('/api/v7/aon/import','POST',{urls:formValue(f,'urls'),folder_id:Number(formValue(f,'folder_id')||0)||null,folder_name:formValue(f,'folder_name'),encounter_id:Number(formValue(f,'encounter_id')||0)||null,publish_codex:checked(f,'publish_codex'),codex_visibility:formValue(f,'codex_visibility'),refresh_existing:checked(f,'refresh_existing')});const modes=(out.results||[]).reduce((a,r)=>(a[r.mode]=(a[r.mode]||0)+1,a),{});const bits=[modes.imported?`${modes.imported} imported`:'',modes.updated?`${modes.updated} refreshed`:'',modes.reused?`${modes.reused} reused`:''].filter(Boolean).join(' · ');toast(bits||'Import complete.');if(out.errors?.length)toast(`${out.errors.length} link${out.errors.length===1?'':'s'} could not be imported.`,true);closeDrawer();await refreshState();switchTab(encounterId?'encounters':'creatures')}catch(err){toast(err.message,true);btn.disabled=false;progress.classList.add('hidden')}};
    });
  }

  // -----------------------------------------------------------------------
  // Encounters
  // -----------------------------------------------------------------------
  function renderEncounters(){
    const rows=state.encounters||[];
    $('#v7EncounterGrid').innerHTML=rows.length?rows.map(enc=>{
      const b=enc.budget||{},extreme=Number(b.budgets?.Extreme||160),pct=Math.min(100,Math.round(Number(b.xp||0)/Math.max(1,extreme)*100));
      const variant=b.rules_variant==='proficiency_without_level'?'PWL':'Standard';
      const incomplete=b.complete===false?'<span class="v7-meta-warning">XP override needed</span>':'';
      return `<article class="v7-encounter-card"><div class="v7-card-ribbon"></div><div class="v7-card-copy"><div class="v7-card-meta"><span>${esc(b.difficulty||'Unknown')}</span><span>${Number(b.xp||0)} XP</span><span>${variant}</span><span>Party ${Number(enc.party_size||4)}× L${Number(enc.party_level||1)}</span>${incomplete}</div><h3>${esc(enc.title)}</h3><p>${esc(enc.objective||enc.summary||'No encounter objective noted.')}</p><div class="v7-xp-meter"><i style="--xp:${pct}%"></i></div><div class="v7-xp-label"><span>${Number(b.xp||0)} XP${b.complete===false?' known':''}</span><span>Extreme ${extreme}</span></div><div class="v7-creature-list">${(enc.creatures||[]).map(c=>`<div class="v7-creature-row"><div><strong>${Number(c.quantity||1)}× ${esc(c.name)}</strong><small>Level ${Number(c.level||0)} · ${esc(c.disposition||'enemy')}</small></div></div>`).join('')||'<p class="v7-muted">No creatures yet.</p>'}</div><div class="v7-card-actions"><button class="v7-button ghost" data-edit-encounter="${enc.id}">Edit</button><button class="v7-button" data-prepare-encounter="${enc.id}">Prepare in Foundry</button></div></div></article>`
    }).join(''):'<div class="v7-empty"><span>⚔</span><h3>No encounters prepared.</h3><p>Build one from creatures already in Seeker or add a quick row by name and level.</p></div>';
    $$('[data-edit-encounter]').forEach(b=>b.onclick=()=>openEncounterEditor(Number(b.dataset.editEncounter)));$$('[data-prepare-encounter]').forEach(b=>b.onclick=async()=>{try{const out=await send(`/api/v7/encounters/${b.dataset.prepareEncounter}/prepare-foundry`,'POST');toast(`${out.count} Foundry definition${out.count===1?'':'s'} queued.`);setTimeout(refreshState,800)}catch(err){toast(err.message,true)}})
  }
  $('[data-v7-new-encounter]')?.addEventListener('click',()=>openEncounterEditor(null));
  async function openEncounterEditor(id){
    let enc=id?(state.encounters||[]).find(x=>Number(x.id)===Number(id)):null;
    if(id&&!enc){try{enc=await send(`/api/v7/encounters/${id}`)}catch(err){return toast(err.message,true)}}
    enc=enc||{title:'',summary:'',party_level:1,party_size:4,status:'prepared',objective:'',terrain:'',tactics:'',reinforcements:'',treasure:'',secrets:'',creatures:[],budget:{},data:{rules_variant:'standard'}};
    const creatureEntities=(state.entities||[]).filter(e=>['monster','creature','npc'].includes(e.kind));
    const opts=creatureEntities.map(e=>`<option value="${e.id}">${esc(e.name)} · L${esc(e.data?.level??'?')}</option>`).join('');
    const budget=enc.budget||{};
    const rulesVariant=budget.rules_variant||enc.data?.rules_variant||'standard';
    const isPwl=rulesVariant==='proficiency_without_level';
    const breakdownByRow=new Map((budget.breakdown||[]).map(row=>[String(row.row_id),row]));
    const creatureRows=(enc.creatures||[]).map(c=>{
      const part=breakdownByRow.get(String(c.id));
      const xpLine=part?.per_xp==null?'XP override required':`${Number(part.per_xp)} XP each · ${Number(part.total_xp)} total${part.source==='override'?' · manual':''}`;
      return `<div class="v7-creature-row"><div><strong>${Number(c.quantity||1)}× ${esc(c.name)}</strong><small>Level ${Number(c.level||0)} · ${esc(c.disposition||'enemy')} · ${esc(xpLine)}</small></div><button class="v7-inline-icon" type="button" data-delete-enc-row="${c.id}" aria-label="Remove creature">×</button></div>`;
    }).join('')||'<p class="v7-muted">No creatures added yet.</p>';
    const warningHtml=(budget.warnings||[]).map(w=>`<div class="v7-encounter-warning"><span>!</span><p>${esc(w)}</p></div>`).join('');
    const rulesNote=isPwl
      ? '<div class="v7-rules-callout active"><span>◇</span><div><strong>Proficiency without Level</strong><p>Uses the GM Core no-level creature XP table from party level −7 to +7. Threat budgets and party-size adjustments stay the same. Creatures outside that published range require a manual XP override.</p></div></div>'
      : '<div class="v7-rules-callout"><span>◇</span><div><strong>Standard PF2e encounter math</strong><p>Uses the normal level-difference creature XP values. Switch this encounter to Proficiency without Level when your campaign uses that variant.</p></div></div>';
    const html=`<div class="v7-editor-section"><h3>Encounter frame</h3><form id="v7EncounterForm"><div class="v7-form-grid">${field('Title','title',enc.title)}${field('Status','status',enc.status,{options:[['prepared','Prepared'],['live','Live'],['resolved','Resolved'],['queued','Queued to Foundry']]})}${field('Party level','party_level',enc.party_level,{type:'number'})}${field('Party size','party_size',enc.party_size,{type:'number'})}${field('Rules math','rules_variant',rulesVariant,{options:[['standard','Standard PF2e'],['proficiency_without_level','Proficiency without Level']]})}${field('Objective','objective',enc.objective,{type:'textarea',wide:true})}${field('Terrain / hazards','terrain',enc.terrain,{type:'textarea',wide:true})}${field('Tactics','tactics',enc.tactics,{type:'textarea',wide:true})}${field('Reinforcements / contingencies','reinforcements',enc.reinforcements,{type:'textarea',wide:true})}${field('Treasure','treasure',enc.treasure,{type:'textarea',wide:true})}${field('Secrets','secrets',enc.secrets,{type:'textarea',wide:true})}</div>${rulesNote}<div class="v7-form-actions"><button class="v7-button ghost" type="button" data-v7-cancel>Cancel</button>${id?'<button class="v7-button ghost" type="button" data-enc-prepare>Prepare in Foundry</button>':''}<button class="v7-button">Save encounter</button></div></form></div>
      ${id?`<div class="v7-editor-section"><div class="v7-budget-banner"><div><span class="eyebrow">${isPwl?'PF2E · PWL BUDGET':'PF2E BUDGET'}</span><strong>${Number(budget.xp||0)} XP${budget.complete===false?' known':''}</strong><small>${esc(budget.difficulty||'Unrated')} · ${Number(enc.party_size||4)} level ${Number(enc.party_level||1)} PCs · ${esc(budget.rules_label||'Standard PF2e')}</small></div><div class="v7-xp-track"><i style="width:${Math.min(100,Number(budget.xp||0)/Math.max(1,Number(budget.budgets?.Extreme||160))*100)}%"></i></div></div>${warningHtml}<div class="v7-inline-head"><h3>Creatures</h3><button class="v7-button ghost small" type="button" data-enc-import-aon>⇣ Import AoN</button></div><div class="v7-creature-list">${creatureRows}</div><form id="v7EncounterCreatureForm" class="v7-subform"><div class="v7-form-grid"><label class="v7-field">From entity<select name="entity_id"><option value="">Quick creature…</option>${opts}</select></label>${field('Name','name','')}${field('Level','level','0',{type:'number'})}${field('Quantity','quantity','1',{type:'number'})}${field('Disposition','disposition','enemy',{options:[['enemy','Enemy'],['neutral','Neutral'],['ally','Ally']]})}${field('XP override','xp_override','',{type:'number',placeholder:isPwl?'Only needed outside party level ±7':'Optional manual XP'})}</div><button class="v7-button ghost" type="submit">＋ Add creature</button></form></div>`:'<div class="v7-danger-note">Save the encounter once, then add creatures. Seeker will calculate the selected PF2e XP budget automatically.</div>'}`;
    openDrawer(id?enc.title:'Build encounter','ENCOUNTER BUILDER',html,body=>{
      $('[data-v7-cancel]',body).onclick=closeDrawer;
      const f=$('#v7EncounterForm',body);
      f.elements.rules_variant?.addEventListener('change',()=>{
        const callout=$('.v7-rules-callout',body);if(!callout)return;
        const pwl=f.elements.rules_variant.value==='proficiency_without_level';
        callout.classList.toggle('active',pwl);
        callout.querySelector('strong').textContent=pwl?'Proficiency without Level':'Standard PF2e encounter math';
        callout.querySelector('p').textContent=pwl?'Uses the GM Core no-level creature XP table from party level −7 to +7. Threat budgets and party-size adjustments stay the same. Creatures outside that published range require a manual XP override.':'Uses the normal level-difference creature XP values. Switch this encounter to Proficiency without Level when your campaign uses that variant.';
      });
      f.onsubmit=async ev=>{ev.preventDefault();try{const out=await send('/api/v7/encounters','POST',{id:id||undefined,session_id:sessionId(),title:formValue(f,'title'),summary:enc.summary||'',status:formValue(f,'status'),party_level:Number(formValue(f,'party_level')||1),party_size:Number(formValue(f,'party_size')||4),objective:formValue(f,'objective'),terrain:formValue(f,'terrain'),tactics:formValue(f,'tactics'),reinforcements:formValue(f,'reinforcements'),treasure:formValue(f,'treasure'),secrets:formValue(f,'secrets'),data:{...(enc.data||{}),rules_variant:formValue(f,'rules_variant')}});toast('Encounter saved.');closeDrawer();await refreshState();openEncounterEditor(Number(out.id))}catch(err){toast(err.message,true)}};
      $('[data-enc-import-aon]',body)?.addEventListener('click',()=>{closeDrawer();openAonImporter(id)});
      const cf=$('#v7EncounterCreatureForm',body);
      if(cf){
        cf.elements.entity_id.onchange=()=>{const e=entityById(cf.elements.entity_id.value);if(e){cf.elements.name.value=e.name;cf.elements.level.value=e.data?.level??0}};
        cf.onsubmit=async ev=>{ev.preventDefault();const e=entityById(cf.elements.entity_id.value),rawOverride=formValue(cf,'xp_override').trim();try{await send(`/api/v7/encounters/${id}/creatures`,'POST',{entity_id:e?.id||null,prepared_content_id:e?.data?.prepared_content_id||null,name:formValue(cf,'name'),level:Number(formValue(cf,'level')||0),quantity:Number(formValue(cf,'quantity')||1),disposition:formValue(cf,'disposition'),xp_override:rawOverride===''?null:Number(rawOverride)});toast('Creature added.');closeDrawer();await refreshState();openEncounterEditor(id)}catch(err){toast(err.message,true)}};
      }
      $$('[data-delete-enc-row]',body).forEach(b=>b.onclick=async()=>{try{await send(`/api/v7/encounters/${id}/creatures/${b.dataset.deleteEncRow}`,'DELETE');closeDrawer();await refreshState();openEncounterEditor(id)}catch(err){toast(err.message,true)}});
      $('[data-enc-prepare]',body)?.addEventListener('click',async()=>{try{const out=await send(`/api/v7/encounters/${id}/prepare-foundry`,'POST');toast(`${out.count} Foundry actor definition${out.count===1?'':'s'} queued.`);closeDrawer();setTimeout(refreshState,800)}catch(err){toast(err.message,true)}});
    });
  }

  // -----------------------------------------------------------------------
  // Loot
  // -----------------------------------------------------------------------
  function renderLoot(){
    const rows=state.loot||[];$('#v7LootGrid').innerHTML=rows.length?rows.map(pool=>`<article class="v7-loot-card"><div class="v7-card-ribbon"></div><div class="v7-card-copy"><div class="v7-card-meta"><span>${esc(pool.status)}</span><span>${(pool.items||[]).reduce((n,i)=>n+Number(i.remaining||0),0)} remaining</span></div><h3>${esc(pool.title)}</h3><p>${esc(pool.note||'Available to the party.')}</p><div class="v7-loot-items">${(pool.items||[]).map(i=>`<div class="v7-loot-row"><div><strong>${Number(i.remaining||0)}× ${esc(i.name)}</strong><small>${esc(i.description||'No description.')}</small></div></div>`).join('')||'<p class="v7-muted">No items in this drop.</p>'}</div><div class="v7-card-actions"><button class="v7-button ghost" data-edit-loot="${pool.id}">Edit drop</button></div></div></article>`).join(''):'<div class="v7-empty"><span>◆</span><h3>No loot drops.</h3><p>Create one during prep or in the moment.</p></div>';$$('[data-edit-loot]').forEach(b=>b.onclick=()=>openLootEditor(Number(b.dataset.editLoot)));
  }
  $('[data-v7-new-loot]')?.addEventListener('click',()=>openLootEditor(null));
  function openLootEditor(id){
    let pool=id?(state.loot||[]).find(x=>Number(x.id)===Number(id)):null;
    pool=pool||{title:'',note:'',status:'open',visibility:'players',items:[]};
    const itemEntities=(state.entities||[]).filter(e=>['item','feat','weapon','armor','consumable','equipment'].includes(e.kind));
    const opts=itemEntities.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.kind)}</option>`).join('');
    const itemRows=(pool.items||[]).map(i=>`<div class="v7-loot-row"><div><strong>${Number(i.remaining||0)}/${Number(i.quantity||0)} · ${esc(i.name)}</strong><small>${esc(i.description||'')}</small></div></div>`).join('')||'<p class="v7-muted">Empty.</p>';
    const html=`<div class="v7-editor-section"><h3>Drop</h3><form id="v7LootForm"><div class="v7-form-grid">${field('Title','title',pool.title)}${field('Status','status',pool.status,{options:[['open','Open'],['closed','Closed']]})}${field('Note','note',pool.note,{type:'textarea',wide:true})}</div><div class="v7-form-actions"><button class="v7-button ghost" type="button" data-v7-cancel>Cancel</button><button class="v7-button">Save drop</button></div></form></div>
      ${id?`<div class="v7-editor-section"><h3>Items on the table</h3><div class="v7-loot-items">${itemRows}</div><form id="v7LootItemForm" class="v7-subform"><div class="v7-form-grid"><label class="v7-field">From entity<select name="entity_id"><option value="">Quick item…</option>${opts}</select></label>${field('Item name','name','')}${field('Quantity','quantity','1',{type:'number'})}${field('Description','description','',{wide:true})}</div><button class="v7-button ghost">＋ Add item</button></form></div>`:''}`;
    openDrawer(id?pool.title:'New loot drop','LIVE LOOT',html,body=>{
      $('[data-v7-cancel]',body).onclick=closeDrawer;
      const f=$('#v7LootForm',body);
      f.onsubmit=async ev=>{ev.preventDefault();try{const out=await send('/api/v7/loot','POST',{id:id||undefined,session_id:sessionId(),title:formValue(f,'title'),note:formValue(f,'note'),status:formValue(f,'status'),visibility:'players'});toast('Loot drop saved.');closeDrawer();await refreshState();openLootEditor(Number(out.id))}catch(err){toast(err.message,true)}};
      const itemForm=$('#v7LootItemForm',body);
      if(itemForm){
        itemForm.elements.entity_id.onchange=()=>{const e=entityById(itemForm.elements.entity_id.value);if(e){itemForm.elements.name.value=e.name;itemForm.elements.description.value=e.summary||''}};
        itemForm.onsubmit=async ev=>{ev.preventDefault();const e=entityById(itemForm.elements.entity_id.value);try{await send(`/api/v7/loot/${id}/items`,'POST',{entity_id:e?.id||null,prepared_content_id:e?.data?.prepared_content_id||null,name:formValue(itemForm,'name'),quantity:Number(formValue(itemForm,'quantity')||1),description:formValue(itemForm,'description')});toast('Item added to drop.');closeDrawer();await refreshState();openLootEditor(id)}catch(err){toast(err.message,true)}};
      }
    });
  }

  // -----------------------------------------------------------------------
  // Knowledge / Recall Knowledge
  // -----------------------------------------------------------------------
  let knowledgeQuery='';function renderKnowledgeList(){let rows=(state.entities||[]).filter(e=>['monster','creature','npc','lore','faction','place','item'].includes(e.kind));if(knowledgeQuery)rows=rows.filter(e=>`${e.name} ${e.summary}`.toLowerCase().includes(knowledgeQuery));$('#v7KnowledgeEntityList').innerHTML=rows.map(e=>`<button data-knowledge-entity="${e.id}"><span>${kindIcon(e.kind)}</span><div><strong>${esc(e.name)}</strong><small>${esc(e.kind)}</small></div></button>`).join('');$$('[data-knowledge-entity]').forEach(b=>b.onclick=()=>openKnowledgeEntity(Number(b.dataset.knowledgeEntity)))}$('[data-v7-knowledge-search]')?.addEventListener('input',e=>{knowledgeQuery=e.currentTarget.value.trim().toLowerCase();renderKnowledgeList()});
  async function openKnowledgeEntity(id){
    try{
      const e=await send(`/api/v7/entities/${id}`);
      $$('[data-knowledge-entity]').forEach(b=>b.classList.toggle('active',String(b.dataset.knowledgeEntity)===String(id)));
      const memberOptions=(state.members||[]).map(m=>`<option value="${m.id}">${esc(m.label)}</option>`).join('');
      const disclosureOptions=f=>{
        const modes=f.available_disclosures||['exact'];
        return [['exact','Exact'],['vague','Vague'],['comparative','Comparative']].map(([v,l])=>`<option value="${v}" ${modes.includes(v)?'':'disabled'}>${l}${modes.includes(v)?'':' · not written'}</option>`).join('');
      };
      const factChecks=(e.facts||[]).map(f=>`<article class="v7-recall-fact-row"><label><input type="checkbox" name="fact" value="${f.id}"><span><strong>${esc(f.title)}</strong><small>${esc(f.tier)} · ${esc(f.body)}</small></span></label><select data-recall-mode="${f.id}" aria-label="Disclosure detail">${disclosureOptions(f)}</select></article>`).join('');
      const observations=(e.observations||[]).map(o=>`<article class="v7-observation-card ${esc(o.status||'inferred')}"><header><div><small>${esc(o.author_label||'Player')} · ${esc(o.visibility)}</small><strong>${esc(o.title)}</strong></div><span>${esc(o.status||'inferred')}</span></header>${o.body?`<p>${esc(o.body)}</p>`:''}${o.kind==='range'?`<div class="v7-range-readout"><b>${o.lower_bound??'?'}</b><span>to</span><b>${o.upper_bound??'?'}</b></div>`:''}<footer><button class="v7-button ghost tiny" data-review-observation="${o.id}" data-status="confirmed">✓ Confirm</button><button class="v7-button ghost tiny" data-review-observation="${o.id}" data-status="rejected">× Reject</button></footer></article>`).join('')||'<p class="v7-muted">No player deductions yet.</p>';
      const facts=(e.facts||[]).map(f=>{
        const mechanics=f.mechanics||{},d=mechanics.disclosures||{};
        return `<article class="v7-fact-card"><header><div><h4>${esc(f.title)}</h4><span class="v7-tier">${esc(f.tier)}</span></div><select data-direct-mode="${f.id}">${disclosureOptions(f)}</select></header><p><b>Exact:</b> ${esc(f.body)}</p>${d.vague?.body?`<p class="v7-disclosure-preview"><b>Vague:</b> ${esc(d.vague.body)}</p>`:''}${d.comparative?.body?`<p class="v7-disclosure-preview"><b>Comparative:</b> ${esc(d.comparative.body)}</p>`:''}<div class="v7-card-actions"><select data-fact-player="${f.id}"><option value="">Reveal to…</option><option value="party">Entire party</option>${memberOptions}</select><button class="v7-button ghost small" data-reveal-fact="${f.id}">Reveal</button></div></article>`;
      }).join('')||'<p class="v7-muted">No structured facts yet.</p>';
      $('#v7KnowledgeEditor').innerHTML=`<header class="v7-panel-head"><div><span class="eyebrow">${esc(e.kind)}</span><h2>${esc(e.name)}</h2></div><button class="v7-button ghost small" data-edit-knowledge-entity>Edit entity</button></header><div class="v7-disclosure-legend"><div><strong>Exact</strong><small>Full number or mechanic</small></div><div><strong>Vague</strong><small>Qualitative clue, no exact value</small></div><div><strong>Comparative</strong><small>Highest, lowest, stronger, weaker…</small></div></div><div class="v7-fact-grid">${facts}</div><div class="v7-recall-box"><span class="eyebrow">RECALL KNOWLEDGE</span><h3>Resolve and reveal</h3><form id="v7RecallForm"><div class="v7-form-grid"><label class="v7-field">Player<select name="invite_id"><option value="">Choose player…</option>${memberOptions}</select></label>${field('Skill','skill','Arcana',{options:[['Arcana','Arcana'],['Nature','Nature'],['Occultism','Occultism'],['Religion','Religion'],['Society','Society'],['Crafting','Crafting']]})}${field('Result','result','',{type:'number'})}${field('DC','dc',e.data?.recall_dc||'',{type:'number'})}</div><div class="v7-editor-section"><h3>Reveal on this result</h3>${factChecks||'<p class="v7-muted">Add knowledge facts to use targeted reveals.</p>'}</div><button class="v7-button">Record Recall Knowledge</button></form></div><div class="v7-editor-section"><div class="v7-section-title"><div><span class="eyebrow">PLAYER INTELLIGENCE</span><h3>Field deductions</h3></div><small>Player-authored notes are inference until you confirm them.</small></div><div class="v7-observation-grid">${observations}</div></div>`;
      $('[data-edit-knowledge-entity]').onclick=()=>openEntityEditor(id);
      $$('[data-reveal-fact]').forEach(b=>b.onclick=async()=>{const target=$(`[data-fact-player="${b.dataset.revealFact}"]`)?.value,mode=$(`[data-direct-mode="${b.dataset.revealFact}"]`)?.value||'exact';if(!target)return toast('Choose a player or the party.',true);try{await send(`/api/v7/facts/${b.dataset.revealFact}/reveal`,'POST',{invite_id:target==='party'?'party':Number(target),party:target==='party',disclosure_mode:mode,session_id:sessionId()});toast(`${mode[0].toUpperCase()+mode.slice(1)} clue revealed${target==='party'?' to the party':''}.`)}catch(err){toast(err.message,true)}});
      $$('[data-review-observation]').forEach(b=>b.onclick=async()=>{try{await send(`/api/v7/observations/${b.dataset.reviewObservation}/review`,'POST',{status:b.dataset.status});toast(`Player deduction ${b.dataset.status}.`);openKnowledgeEntity(id)}catch(err){toast(err.message,true)}});
      $('#v7RecallForm').onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget;if(!formValue(f,'invite_id'))return toast('Choose a player.',true);const reveals=$$('input[name="fact"]:checked',f).map(x=>({fact_id:Number(x.value),mode:$(`[data-recall-mode="${x.value}"]`,f)?.value||'exact'}));try{const out=await send(`/api/v7/entities/${id}/recall`,'POST',{invite_id:Number(formValue(f,'invite_id')),skill:formValue(f,'skill'),result:formValue(f,'result'),dc:formValue(f,'dc'),reveal_facts:reveals,session_id:sessionId()});toast(`Recall Knowledge recorded${out.degree?` · ${out.degree}`:''}.`)}catch(err){toast(err.message,true)}};
    }catch(err){toast(err.message,true)}
  }

  // -----------------------------------------------------------------------
  // Memory
  // -----------------------------------------------------------------------
  async function runMemorySearch(){const q=$('#v7MemoryQuery').value.trim();if(!q)return;const host=$('#v7MemoryResults');host.innerHTML='<div class="v7-empty"><p>Searching the campaign…</p></div>';try{const rows=await send(`/api/v7/memory?q=${encodeURIComponent(q)}`);host.innerHTML=rows.length?rows.map(r=>`<a class="v7-memory-hit" href="${esc(r.href||'#')}"><span>${esc(r.kind)}</span><div><h3>${esc(r.title)}</h3><p>${esc(r.excerpt||'')}</p></div><small>score ${Number(r.score||0).toFixed(1)} →</small></a>`).join(''):'<div class="v7-empty"><h3>No matching campaign memory.</h3><p>Try a specific name, symbol, location or event.</p></div>'}catch(err){host.innerHTML=`<div class="v7-empty"><p>${esc(err.message)}</p></div>`}}$('#v7MemorySearch')?.addEventListener('click',runMemorySearch);$('#v7MemoryQuery')?.addEventListener('keydown',e=>{if(e.key==='Enter')runMemorySearch()});

  // -----------------------------------------------------------------------
  // Managed Foundry sync
  // -----------------------------------------------------------------------
  function renderSync(){
    const rows=(state.entities||[]).filter(e=>e.sync||['monster','npc','item','feat','weapon'].includes(e.kind));$('#v7SyncGrid').innerHTML=rows.length?rows.map(e=>{const s=e.sync||{};const st=s.status||'unlinked',diffs=s.diffs||[];return `<article class="v7-sync-card"><div class="v7-card-ribbon ${statusClass(st)}"></div><div class="v7-card-copy"><div class="v7-card-meta"><span>${esc(e.kind)}</span><span>${esc(st)}</span></div><h3>${esc(e.name)}</h3><div class="v7-diff-columns"><div><small>SEEKER</small><strong>${esc(e.name)}</strong></div><div><small>FOUNDRY</small><strong>${esc(s.foundry_snapshot?.name||s.foundry_uuid||'Not linked')}</strong></div></div><p class="v7-sync-state ${statusClass(st)}">${esc(st)}${diffs.length?` · ${diffs.length} comparable field${diffs.length===1?'':'s'} differ`:''}</p><div class="v7-card-actions"><button class="v7-button ${s.foundry_uuid?'ghost':''}" data-sync-push="${e.id}">${s.foundry_uuid?'Push update':'Create in Foundry'}</button>${['foundry_changed','conflict'].includes(st)?`<button class="v7-button ghost" data-sync-pull="${e.id}">Accept Foundry</button>`:''}<button class="v7-button ghost" data-sync-open="${e.id}">Compare</button></div></div></article>`}).join(''):'<div class="v7-empty"><h3>No sync-capable entities yet.</h3></div>';$$('[data-sync-push]').forEach(b=>b.onclick=()=>syncEntity(b.dataset.syncPush,'push'));$$('[data-sync-pull]').forEach(b=>b.onclick=()=>syncEntity(b.dataset.syncPull,'accept_foundry'));$$('[data-sync-open]').forEach(b=>b.onclick=()=>openEntityEditor(Number(b.dataset.syncOpen)));
  }
  async function syncEntity(id,mode){try{const out=await send(`/api/v7/entities/${id}/foundry`,'POST',{mode});toast(out.command?'Foundry action queued.':'Foundry snapshot accepted.');setTimeout(refreshState,850)}catch(err){toast(err.message,true)}}

  // -----------------------------------------------------------------------
  // Logic/dependencies
  // -----------------------------------------------------------------------
  $('[data-v7-new-dependency]')?.addEventListener('click',()=>{const opts=(state.entities||[]).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('');openDrawer('New dependency rule','WORLD LOGIC',`<form id="v7DependencyForm"><div class="v7-editor-section"><h3>When this becomes true…</h3><div class="v7-form-grid"><label class="v7-field">Entity<select name="source_entity_id"><option value="">Choose…</option>${opts}</select></label>${field('Field','source_field','status')}${field('Condition','operator','equals',{options:[['equals','Equals'],['not_equals','Does not equal'],['contains','Contains'],['truthy','Is set']]})}${field('Value','expected_value','dead')}</div></div><div class="v7-editor-section"><h3>…warn me about this</h3>${field('Warning','message','',{type:'textarea',wide:true,placeholder:'This NPC is dead but still appears in Session Prep.'})}<div class="v7-form-grid">${field('Severity','severity','warning',{options:[['warning','Warning'],['danger','Danger'],['info','Info']]})}${field('Target label','target_key','')}</div></div><div class="v7-form-actions"><button class="v7-button ghost" type="button" data-v7-cancel>Cancel</button><button class="v7-button">Save rule</button></div></form>`,body=>{$('[data-v7-cancel]',body).onclick=closeDrawer;$('#v7DependencyForm',body).onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{await send('/api/v7/dependencies','POST',{source_entity_id:Number(formValue(f,'source_entity_id')),source_field:formValue(f,'source_field'),operator:formValue(f,'operator'),expected_value:formValue(f,'expected_value'),message:formValue(f,'message'),severity:formValue(f,'severity'),target_type:'session',target_key:formValue(f,'target_key'),active:true});toast('Dependency rule saved.');closeDrawer();await refreshState()}catch(err){toast(err.message,true)}}})});

  // -----------------------------------------------------------------------
  // Assets & token recipes
  // -----------------------------------------------------------------------
  let assetLoaded=false,assetState=null;async function loadAssets(force=false){if(assetLoaded&&!force){renderAssets();return}try{assetState=await send('/api/v7/assets');assetLoaded=true;renderAssets()}catch(err){toast(err.message,true)}}
  function renderAssets(){if(!assetState)return;$('#v7AssetSummary').innerHTML=[['Storage',fmtBytes(assetState.total_bytes)],['Files',assetState.count],['Referenced',assetState.referenced],['Possible orphans',assetState.orphaned]].map(([l,v])=>`<div class="v7-metric"><strong>${esc(v)}</strong><small>${esc(l)}</small></div>`).join('');$('#v7AssetGrid').innerHTML=(assetState.files||[]).map(a=>`<article class="v7-asset-card ${a.references?'':'orphan'}"><div class="v7-asset-thumb" ${/\.(?:png|jpe?g|webp|gif)$/i.test(a.name)?`style="background-image:url('${esc(a.url)}')"`:''}>${/\.(?:png|jpe?g|webp|gif)$/i.test(a.name)?'':'▧'}</div><div><strong title="${esc(a.relative)}">${esc(a.name)}</strong><small>${fmtBytes(a.size_bytes)} · ${a.references} reference${a.references===1?'':'s'}</small></div></article>`).join('');renderTokenRecipes()}
  function renderTokenRecipes(){const host=$('#v7TokenRecipes');host.innerHTML=(state.token_recipes||[]).length?(state.token_recipes||[]).map(r=>`<article class="v7-stack-item"><strong>${esc(r.name)}</strong><small>${esc(r.description||'Reusable Token Forge recipe')}</small></article>`).join(''):'<p class="v7-muted">No campaign recipes yet. Recipes saved in Token Forge will appear here.</p>'}
  $('[data-v7-refresh-assets]')?.addEventListener('click',()=>loadAssets(true));
  function openTokenRecipeEditor(){
    openDrawer('Save token recipe','TOKEN FORGE',`<form id="v7RecipeForm"><div class="v7-editor-section"><h3>Reusable frame style</h3>${field('Recipe name','name','')}${field('Description','description','',{type:'textarea',wide:true})}${field('Settings JSON','settings','{}',{type:'textarea',wide:true})}<p class="v7-muted">Token Forge can save its current controls here automatically. This editor is also useful for copying a recipe between campaigns.</p></div><div class="v7-form-actions"><button class="v7-button ghost" type="button" data-v7-cancel>Cancel</button><button class="v7-button">Save recipe</button></div></form>`,body=>{
      $('[data-v7-cancel]',body).onclick=closeDrawer;
      $('#v7RecipeForm',body).onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;let settings={};try{settings=JSON.parse(formValue(f,'settings')||'{}')}catch{return toast('Settings JSON is invalid.',true)}try{const r=await send('/api/v7/token-recipes','POST',{name:formValue(f,'name'),description:formValue(f,'description'),settings});state.token_recipes=[...(state.token_recipes||[]).filter(x=>x.name!==r.name),r];renderTokenRecipes();toast('Token recipe saved.');closeDrawer()}catch(err){toast(err.message,true)}};
    });
  }
  $('[data-v7-new-recipe]')?.addEventListener('click',openTokenRecipeEditor);

  // -----------------------------------------------------------------------
  // Access, integrations, health
  // -----------------------------------------------------------------------
  const permissionLabel=p=>p.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
  function renderAccess(){
    const roles=['owner','co-gm','player','spectator'],perms=state.all_permissions||[];
    $('#v7PermissionMatrix').innerHTML=`<table><thead><tr><th>Capability</th>${roles.map(r=>`<th>${esc(r)}</th>`).join('')}</tr></thead><tbody>${perms.map(p=>`<tr><td><strong>${esc(permissionLabel(p))}</strong><small>${esc(permissionHelp(p))}</small></td>${roles.map(r=>{const on=!!state.permissions?.[r]?.[p];return `<td><button class="v7-toggle ${on?'on':''}" data-role="${r}" data-permission="${p}" ${!state.current_is_owner?'disabled':''} title="${on?'Allowed':'Not allowed'}"><i></i></button></td>`}).join('')}</tr>`).join('')}</tbody></table>`;
    $$('[data-role][data-permission]').forEach(b=>b.onclick=async()=>{if(!state.current_is_owner)return;const role=b.dataset.role,p=b.dataset.permission;const next=!state.permissions[role][p];const body={...state.permissions[role],[p]:next};try{state.permissions[role]=await send(`/api/v7/permissions/roles/${role}`,'PUT',body);renderAccess();toast(`${role} permissions updated.`)}catch(err){toast(err.message,true)}});
    const members=state.members||[];const memberHost=$('#v7MemberPermissions');
    if(memberHost)memberHost.innerHTML=members.length?members.map(m=>`<article class="v7-member-card"><header><div><strong>${esc(m.label||m.name||'Player')}</strong><small>${esc(m.v7_role||m.role||'player')} · ${Object.keys(m.v7_overrides||{}).length} override${Object.keys(m.v7_overrides||{}).length===1?'':'s'}</small></div><button class="v7-button ghost small" data-member-permissions="${m.id}" ${!state.current_is_owner?'disabled':''}>Customize</button></header><div class="v7-member-cap-row">${perms.filter(p=>m.v7_permissions?.[p]).slice(0,5).map(p=>`<span>${esc(permissionLabel(p))}</span>`).join('')||'<span>Read-only defaults</span>'}</div></article>`).join(''):'<p class="v7-muted">No campaign members.</p>';
    $$('[data-member-permissions]').forEach(b=>b.onclick=()=>openMemberPermissions(Number(b.dataset.memberPermissions)));
    $('#v7IntegrationGrid').innerHTML=(state.integrations||[]).map(i=>`<article class="v7-integration-card"><small>${esc((i.capabilities||[]).join(' · '))}</small><h3>${esc(i.title)}</h3><p>${esc(i.description)}</p></article>`).join('');
  }
  function openMemberPermissions(memberId){
    const m=(state.members||[]).find(x=>Number(x.id)===Number(memberId));if(!m)return;
    const perms=state.all_permissions||[],overrides=m.v7_overrides||{},role=m.v7_role||m.role||'player';
    const rows=perms.map(p=>{const inherited=!!state.permissions?.[role]?.[p],ov=Object.prototype.hasOwnProperty.call(overrides,p)?String(!!overrides[p]):'inherit';return `<label class="v7-override-row"><span><strong>${esc(permissionLabel(p))}</strong><small>${esc(permissionHelp(p))} · role default: ${inherited?'allow':'deny'}</small></span><select name="${esc(p)}"><option value="inherit" ${ov==='inherit'?'selected':''}>Inherit</option><option value="true" ${ov==='true'?'selected':''}>Allow</option><option value="false" ${ov==='false'?'selected':''}>Deny</option></select></label>`}).join('');
    openDrawer(m.label||m.name||'Player','ACCESS OVERRIDES',`<form id="v7MemberPermissionForm"><div class="v7-editor-section"><h3>${esc(role)} defaults + exceptions</h3><div class="v7-override-list">${rows}</div></div><div class="v7-form-actions"><button type="button" class="v7-button ghost" data-v7-cancel>Cancel</button><button class="v7-button">Save overrides</button></div></form>`,body=>{
      $('[data-v7-cancel]',body).onclick=closeDrawer;$('#v7MemberPermissionForm',body).onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,payload={};for(const p of perms){const v=formValue(f,p);payload[p]=v==='inherit'?null:v==='true'}try{const saved=await send(`/api/v7/permissions/invites/${memberId}`,'PUT',payload);m.v7_overrides=saved;m.v7_permissions={...state.permissions[role],...saved};toast('Player overrides saved.');closeDrawer();renderAccess()}catch(err){toast(err.message,true)}};
    });
  }
  function permissionHelp(p){return ({view_statblocks:'See exact creature mechanics.',create_player_notes:'Create personal campaign notes and field deductions.',share_player_knowledge:'Share learned facts and deductions with the party.',manage_own_inventory:'Claim and manage own loot.',push_foundry_character:'Use safe character write-backs.',reveal_lore:'Reveal structured facts to players.',edit_entities:'Create relationships and entity state.',edit_monsters:'Create PF2e/bestiary content.',manage_sessions:'Run and close sessions.',edit_canon:'Change durable setting source.',manage_encounters:'Build and prepare encounters.',manage_loot:'Create and distribute loot.',manage_permissions:'Change access rules.',manage_integrations:'Configure external services.'}[p]||'Seeker capability.')} 
  async function runHealth(){const host=$('#v7Health');host.innerHTML='<div><strong>…</strong><small>Checking</small></div>';try{const h=await send('/api/v7/health');host.innerHTML=[['Version',h.version],['Entities',h.entities],['Asset storage',fmtBytes(h.asset_bytes)],['Asset files',h.asset_files],['Continuity warnings',h.dependency_warnings],['Migration backups',h.migration_backups],['Foundry queued',h.foundry_queue?.queued||0],['Foundry failed',h.foundry_queue?.failed||0]].map(([l,v])=>`<div><strong>${esc(v)}</strong><small>${esc(l)}</small></div>`).join('')}catch(err){host.innerHTML=`<div><strong>Failed</strong><small>${esc(err.message)}</small></div>`}}$('[data-v7-health]')?.addEventListener('click',runHealth);

  // Initial render
  function renderAll(){renderScenes();renderWarnings();renderChanges();renderFronts();renderSyncSummary();renderEntityKinds();renderEntities();renderCreatureVault();renderEncounters();renderLoot();renderKnowledgeList();renderSync();renderTokenRecipes();renderAccess()}
  renderAll();runHealth();
})();
